window.__votdWeek && window.__votdWeek({"week":"2028-12-04","reading":"Moroni 7–9","days":[{"d":"2028-12-04","ref":"Moroni 7:6","b":"Moroni","c":7,"v":6,"he":"כִּי הִנֵּה אָמַר אֱלֹהִים אִישׁ רָע לֹא־יוּכַל לַעֲשׂוֹת הַטּוֹב כִּי־אִם יַקְרִיב מַתָּנָה אוֹ יִתְפַּלֵּל אֶל־אֱלֹהִים בִּלְתִּי אִם־יַעֲשֶׂה בְּלֵב שָׁלֵם לֹא־יוֹעִיל לוֹ מְאוּמָה׃","en":"For behold, God hath said a man being evil cannot do that which is good; for if he offereth a gift, or prayeth unto God, except he shall do it with real intent it profiteth him nothing."},{"d":"2028-12-05","ref":"Moroni 7:47","b":"Moroni","c":7,"v":47,"he":"אַךְ הַחֶסֶד הוּא אַהֲבַת הַמָּשִׁיחַ הַטְּהוֹרָה וְהוּא יַעֲמֹד לָעַד וְכׇל־הַנִּמְצָא בוֹ בַּיּוֹם הָאַחֲרוֹן יִיטַב לוֹ׃","en":"But charity is the pure love of Christ, and it endureth forever; and whoso is found possessed of it at the last day, it shall be well with him."},{"d":"2028-12-06","ref":"Moroni 7:48","b":"Moroni","c":7,"v":48,"he":"לָכֵן אַחַי הָאֲהוּבִים הִתְפַּלְּלוּ אֶל־הָאָב בְּכׇל־כֹּחַ הַלֵּב לְמַעַן תִּמָּלְאוּ בַחֶסֶד הַזֶּה אֲשֶׁר־נָתַן לְכׇל־הַהֹלְכִים בֶּאֱמֶת אַחֲרֵי בְנוֹ יֵשׁוּעַ הַמָּשִׁיחַ לְמַעַן תִּהְיוּ בְּנֵי אֱלֹהִים לְמַעַן כַּאֲשֶׁר יֵרָאֶה נִהְיֶה כָמֹהוּ כִּי נִרְאֵהוּ כַּאֲשֶׁר הוּא לְמַעַן תִּהְיֶה לָנוּ הַתִּקְוָה הַזֹּאת לְמַעַן נִטָּהֵר כַּאֲשֶׁר הוּא טָהוֹר אָמֵן׃","en":"Wherefore, my beloved brethren, pray unto the Father with all the energy of heart, that ye may be filled with this love, which he hath bestowed upon all who are true followers of his Son, Jesus Christ; that ye may become the sons of God; that when he shall appear we shall be like him, for we shall see him as he is; that we may have this hope; that we may be purified even as he is pure. Amen."},{"d":"2028-12-07","ref":"Moroni 8:3","b":"Moroni","c":8,"v":3,"he":"זוֹכֵר אֲנִי אוֹתְךָ תָּמִיד בִּתְפִלּוֹתַי וּמִתְפַּלֵּל מֵאֵין הֲפֻגוֹת אֶל־הָאֱלֹהִים הָאָב בְּשֵׁם יֶלֶד קׇדְשׁוֹ יֵשׁוּעַ כִּי־הוּא בְּטוּבוֹ וְחַסְדּוֹ אֵין־קֵץ יִשְׁמׇרְךָ בַּעֲמִידַת הָאֱמוּנָה בִּשְׁמוֹ עַד־הַקֵּץ׃","en":"I am mindful of you always in my prayers, continually praying unto God the Father in the name of his Holy Child, Jesus, that he, through his infinite goodness and grace, will keep you through the endurance of faith on his name to the end."},{"d":"2028-12-08","ref":"Moroni 8:18","b":"Moroni","c":8,"v":18,"he":"כִּי יוֹדֵעַ אֲנִי כִּי אֱלֹהִים אֵינֶנּוּ אֵל נוֹשֵׂא פָּנִים וְלֹא יְצוּר מִשְׁתַּנֶּה כִּי־הוּא בִּלְתִּי מִשְׁתַּנֶּה מֵעוֹלָם וְעַד־עוֹלָם׃","en":"For I know that God is not a partial God, neither a changeable being; but he is unchangeable from all eternity to all eternity."},{"d":"2028-12-09","ref":"Moroni 8:25","b":"Moroni","c":8,"v":25,"he":"וְרֵאשִׁית פְּרִי הַתְּשׁוּבָה הִיא הַטְּבִילָה וְהַטְּבִילָה בָּאָה בֶּאֱמוּנָה לְהַשְׁלִים אֶת־הַמִּצְוֹת וְהַשְׁלָמַת הַמִּצְוֹת מֵבִיא כִּי נִסְלְחוּ חֲטָאִים׃","en":"And the first fruits of repentance is baptism; and baptism cometh by faith unto the fulfilling the commandments; and the fulfilling the commandments bringeth remission of sins;"},{"d":"2028-12-10","ref":"Moroni 9:14","b":"Moroni","c":9,"v":14,"he":"אֵיךְ נְצַפֶּה כִּי יַחְשֹׁךְ אֱלֹהִים יָדוֹ מִמִּשְׁפָּט עָלֵינוּ׃","en":"How can we expect that God will stay his hand in judgment against us?"}]});
